/*
 * Spike allocator: allocations of 2 KB or more go to PSRAM on the device.
 * The z-buffer and display lists are the big ones; the small context state
 * stays in fast internal RAM.
 */

static inline void required_for_compilation_(){
	return;
}

#if TGL_FEATURE_CUSTOM_MALLOC == 1
#include "zgl.h"
#include <string.h>
#ifdef ESP_PLATFORM
#include <esp_heap_caps.h>
#endif

long spike_psram_bytes = 0;
long spike_internal_bytes = 0;

void gl_free(void* p) { free(p); }

void* gl_malloc(GLint size) {
#ifdef ESP_PLATFORM
	if (size >= 2048) {
		void* p = heap_caps_malloc(size, MALLOC_CAP_SPIRAM);
		if (p) spike_psram_bytes += size;
		return p;
	}
#endif
	spike_internal_bytes += size;
	return malloc(size);
}

void* gl_zalloc(GLint size) {
	void* p = gl_malloc(size);
	if (p) memset(p, 0, size);
	return p;
}
#endif

